+      </div>
+
+      <div class="example">
+        <h2 class="question">
+          <button class="toggle" type="button" aria-expanded="false" aria-controls="faq-5-details" id="faq-5-button">
+            How can I tell if my cat may be sick?
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+        </h2>
